>                                        <th>Email người đặt</th>                                        <th class="text-center">Tổng tiền</th>                                        <th>Trạng thái thanh toán</th>                                        <th class="text-center">Chức năng</th>                                    </tr>                                </thead>                                                <tbody>                                    <?php                                    foreach ($rows as $row) {                                        if ($row['transaction_status'] == 0) {                                            $tr_view = 'warning';                                            $transaction_status = 'Chưa thanh toán';                                        } elseif ($row['transaction_status'] == 1) {                                            $tr_view = 'info';                                            $transaction_status = 'Đang thanh toán, chờ phản hồi';                                        } else {                                            $tr_view = '';                                            $transaction_status = 'Đã thanh toán, tiền đã nhận'; //4                                        }                                        ?>                                        <tr class="<?php echo $tr_view; ?>">                                            <td class="text-center">                                                <input type="checkbox" class="check flat-blue" value="<?php echo $row['order_id']; ?>" name="idcheck[]">                                            </td>                                            <td><?php echo $row['order_code']; ?></td>                                            <td class="text-center"><?php echo display_date($row['add_time']); ?></td>                                            <td><a href="mailto:<?php echo $row['order_email']; ?>" style="text-decoration:underline" target="_blank"><?php echo $row['order_email']; ?></a></td>                                            <td class="text-right"><?php echo formatRice($row['order_amount']); ?> vnđ</td>                                            <td>                                                <?php echo $transaction_status; ?>                                                                            </td>                                            <td class="text-center">                                                <?php                                                $link_or_view = get_admin_url('orders/or_view/' . $row['order_id']);                                                if ($row['transaction_status'] == 0) {                                                    ?>                                                    <em class="fa fa-eye fa-lg">&nbsp;</em> <a href="<?php echo $link_or_view; ?>" title="">Xem</a>                                                    &nbsp;-&nbsp;<em class="fa fa-trash-o fa-lg">&nbsp;</em> <a href="<?php echo get_admin_url('orders/delete/' . $row['order_id']); ?>" class="delete_bootbox" title="Xóa">Xóa</a>                                                    <?php                                                } else {                                                    ?>                                                    <em class="fa fa-eye fa-lg">&nbsp;</em> <a href="<?php echo $link_or_view; ?>" title="">Xem</a>                                                    <?php                                                }                                                ?>                                            </td>                                        </tr>                                        <?php                                    }                                    ?>                                </tbody>                            </table>                        </div>                    </form>            